<?php if (!$configured): ?><div class="card p-5 mb-4 border-amber-300 bg-amber-50"><b class="flex items-center gap-2"><?= icon('triangle-alert', 'w-5 h-5') ?> AI image generation is not configured</b><p class="text-sm mt-2">Add your OpenAI API key to the server's <code class="bg-white px-1 rounded">.env</code> file and reload:</p><pre class="bg-white rounded-lg p-3 text-xs mt-2 overflow-x-auto">OPENAI_API_KEY=sk-...your-key...
AI_IMAGE_MODEL=<?= e($model) ?></pre><p class="text-xs mt-2">See <code>docs/AI_SETUP.md</code>. Nothing is generated until a key is present — no placeholder results are ever shown.</p></div><?php endif; ?>
<div class="grid lg:grid-cols-5 gap-4"><div class="lg:col-span-2"><form id="ai-form" class="card p-5 space-y-4"><h2 class="font-bold">Generate an image</h2><div><label class="label" for="prompt">Prompt</label><textarea class="textarea" id="prompt" name="prompt" required minlength="5" maxlength="1500" placeholder="A wide festive banner of colourful fireworks over a temple at night, warm light, no text"></textarea></div>
  <div class="grid grid-cols-2 gap-3"><div><label class="label">Style</label><select class="select" name="style"><option value="">None</option><?php foreach ($styles as $s): ?><option value="<?= e($s) ?>"><?= e(ucfirst(str_replace('-', ' ', $s))) ?></option><?php endforeach; ?></select></div><div><label class="label">Aspect ratio</label><select class="select" name="aspect"><?php foreach ($aspects as $k => $a): ?><option value="<?= e($k) ?>" <?= $k === 'landscape' ? 'selected' : '' ?>><?= e($a['label']) ?></option><?php endforeach; ?></select></div></div>
  <div><label class="label">Quality</label><select class="select" name="quality"><?php foreach ($qualities as $k => $l): ?><option value="<?= e($k) ?>" <?= $k === 'medium' || $k === 'standard' ? 'selected' : '' ?>><?= e($l) ?></option><?php endforeach; ?></select><p class="hint">Model: <?= e($model) ?></p></div>
  <button id="ai-go" class="btn btn-primary w-full" <?= !$configured ? 'disabled' : '' ?>><?= icon('wand-sparkles', 'w-4 h-4') ?> Generate</button></form></div>
  <div class="lg:col-span-3"><div class="card p-5 min-h-[260px]"><h2 class="font-bold mb-3">Preview</h2><div id="ai-out"><p class="text-sm muted">Your generated image appears here. It stays private until you save it to the Media Library and then explicitly choose it in Banners or Products.</p></div></div></div></div>
<h2 class="font-bold mt-8 mb-3">Generation history</h2><div class="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-6 gap-3"><?php foreach ($history as $h): ?><div class="card overflow-hidden text-xs"><?php if ($h['status'] === 'success'): ?><a href="<?= e(url('/admin/ai-image/' . $h['id'] . '/file')) ?>" target="_blank" class="block aspect-square bg-gray-50"><img src="<?= e(url('/admin/ai-image/' . $h['id'] . '/file')) ?>" class="w-full h-full object-cover" loading="lazy" alt=""></a><?php else: ?><div class="aspect-square bg-red-50 text-red-700 p-2 overflow-auto"><?= e($h['error_message']) ?></div><?php endif; ?>
<div class="p-2.5"><p class="line-clamp-2" title="<?= e($h['prompt']) ?>"><?= e($h['prompt']) ?></p><div class="muted mt-1"><?= e(date('d M, h:i A', strtotime($h['created_at']))) ?></div><?php if ($h['status'] === 'success'): ?><div class="flex gap-1 mt-2"><?php if ($h['media_id']): ?><span class="badge bg-green-100 text-green-700">In library</span><?php else: ?><button type="button" class="btn btn-soft btn-sm !px-2" data-ai-save="<?= (int)$h['id'] ?>">Save</button><?php endif; ?><a class="btn btn-outline btn-sm !px-2" href="<?= e(url('/admin/ai-image/' . $h['id'] . '/file?download=1')) ?>">↓</a></div><?php endif; ?></div></div><?php endforeach; if (!$history): ?><p class="muted text-sm col-span-full">No generations yet.</p><?php endif; ?></div>
